# Human overrides of the anchor audit (data/fontanchors_audit/{style}.py).
#
# The audit files are regenerated by run_anchor_audit.py; this file is not.
# Stage 1 of the patch pipeline deletes an anchor marked "delete" here, for
# any reason (copied, colliding, off the style's anchor model); stage 6 then
# gives it the anchor-model candidate, unless a curated anchor overrules it.
# If DELETE_BAD_ANCHORS in font_patching.py is on, stage 1 also deletes every
# anchor the audit says is "bad", unless it is overruled here:
#
#     "keep"    never delete, whatever the audit says
#     "delete"  delete, even if the audit says "suspect" or lists nothing
#
# style -> glyph name -> anchor class (0 above, 2 below) -> "keep" | "delete"

overrides = {
    "regular": {
        # "q": {0: "keep"},
        # Ɯ: above-anchor y 801, 49 below the capital reference (850)
        "uni019C": {0: "delete"},  # (431, 801)
        # Ɗ: D's above-anchor copied without D's 80-unit shift, at y 805
        "uni018A": {0: "delete"},  # (306, 805)
        # Ɣ: y 805, 45 below the capital reference
        "uni0194": {0: "delete"},  # (331, 805)
        # β: below-anchor y -114, inside the descender (ymin -238)
        "beta": {2: "delete"},  # (275, -114)
        # J: below-anchor y -319 is the full-descender reference, but J is not a
        # full descender (ymin about -182)
        "J": {2: "delete"},  # (109, -319)
    },
    "italic": {
        # ɦ: above-anchor y 565, inside the hook; stage 6 gives the ascender candidate
        "uni0266": {0: "delete"},  # (299, 565)
        # Ɯ: above-anchor y 801, 49 below the capital reference (850), and
        # regular's x, not slanted
        "uni019C": {0: "delete"},  # (431, 801)
        # Ɗ: regular's anchors (D's, without the shift; y 805), not slanted
        "uni018A": {0: "delete", 2: "delete"},  # (306, 805), (369, -107)
        # Ɣ: regular's anchor, y 805, not slanted
        "uni0194": {0: "delete"},  # (331, 805)
        # β: regular's anchor, y -114, inside the descender (ymin -235), not slanted
        "beta": {2: "delete"},  # (275, -114)
        # J: below-anchor y -319, not a full descender
        "J": {2: "delete"},  # (109, -319)
    },
    "semibold": {
        # J: below-anchor y -319, not a full descender
        "J": {2: "delete"},  # (109, -319)
    },
    "semibold_italic": {
        # Above-anchors set with the slant (italic anchor model, no K), so an
        # above-mark lands 130-190 units too far right. Stage 6 replaces them
        # with the semibold italic candidate.
        "a": {0: "delete"},  # (379, 645)
        "s": {0: "delete"},  # (326, 645)
        "h": {0: "delete"},  # (469, 645), also at x-height, not ascender
        "J": {0: "delete", 2: "delete"},  # (432, 850), (109, -319), not a full descender
        # Ɯ: above-anchor y 801, 49 below the capital reference (850), and
        # regular's x, not slanted
        "uni019C": {0: "delete"},  # (431, 801)
        # Ɗ: regular's anchors (D's, without the shift; y 805), not slanted
        "uni018A": {0: "delete", 2: "delete"},  # (306, 805), (369, -107)
        # Ɣ: regular's anchor, y 805, not slanted
        "uni0194": {0: "delete"},  # (331, 805)
        # β: regular's anchor, y -114, inside the descender (ymin -233)
        "beta": {2: "delete"},  # (275, -114)
    },
}
